export interface ConnectorConfig {
  githubOwner: string
  githubRepo: string
  githubToken: string
  zendeskSubdomain: string
  zendeskAccessToken: string
  fetch?: typeof fetch
}

export interface ZendeskTicketCreatedPayload {
  type: string
  account_id: number
  id: string
  time: string
  zendesk_event_version: string
  subject: string
  detail: {
    id: string
    subject: string
    description: string
    status: string
    priority: string
    requester_id: string
    submitter_id: string
    assignee_id: string | null
    organization_id: string
    group_id: string
    tags: string[]
    via: { channel: string }
    created_at: string
    updated_at: string
  }
}

export interface HandleResult {
  githubIssueUrl: string
  zendeskTicketId: string
}

async function fetchWithRetry(
  fetchFn: typeof fetch,
  url: string,
  init: RequestInit,
  maxRetries = 3,
  baseMs = 1000,
): Promise<Response> {
  let lastError: Error | null = null
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const res = await fetchFn(url, init)
    if (res.status === 429 || (res.status >= 500 && res.status < 600)) {
      const retryAfter = res.headers.get('retry-after')
      let delayMs: number
      if (retryAfter) {
        const asSec = Number(retryAfter)
        if (!Number.isNaN(asSec)) {
          delayMs = asSec * 1000
        } else {
          const date = new Date(retryAfter)
          delayMs = Number.isNaN(date.getTime()) ? baseMs * 2 ** attempt : Math.max(0, date.getTime() - Date.now())
        }
      } else {
        delayMs = baseMs * 2 ** attempt
      }
      if (delayMs > 0 && !Number.isNaN(delayMs)) {
        await new Promise((r) => setTimeout(r, delayMs))
      }
      lastError = new Error(`Retryable status ${res.status} on ${init.method ?? 'POST'} ${url}`)
      continue
    }
    if (!res.ok) {
      throw new Error(`HTTP ${res.status} on ${init.method ?? 'POST'} ${url}`)
    }
    return res
  }
  throw lastError ?? new Error(`Max retries exceeded on ${init.method ?? 'POST'} ${url}`)
}

export async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (!payload.detail?.id) throw new Error('Missing required field: detail.id')
  if (!payload.detail?.subject) throw new Error('Missing required field: detail.subject')
  if (!payload.detail?.description) throw new Error('Missing required field: detail.description')

  const ticketId = payload.detail.id
  const title = payload.detail.subject
  const body = payload.detail.description

  const githubUrl = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`
  const githubRes = await fetchWithRetry(fetchFn, githubUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.githubToken}`,
      Accept: 'application/vnd.github+json',
      'Content-Type': 'application/json',
      'X-GitHub-Api-Version': '2022-11-28',
    },
    body: JSON.stringify({ title, body }),
  })
  const githubData = (await githubRes.json()) as { html_url: string }
  const githubIssueUrl = githubData.html_url

  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets/${ticketId}.json`
  const commentBody = `GitHub issue created: ${githubIssueUrl}`
  await fetchWithRetry(fetchFn, zendeskUrl, {
    method: 'PUT',
    headers: {
      Authorization: `Bearer ${config.zendeskAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      ticket: {
        comment: {
          body: commentBody,
          public: true,
        },
      },
    }),
  })

  return { githubIssueUrl, zendeskTicketId: ticketId }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, ZendeskTicketCreatedPayload } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      githubOwner: 'octocat',
      githubRepo: 'example',
      githubToken: 'gh-token',
      zendeskSubdomain: 'mysub',
      zendeskAccessToken: 'zd-token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/example/issues/123')
    expect(result.zendeskTicketId).toBe('9876')
  })
})

describe('handle', () => {
  it('creates GitHub issue and posts Zendesk comment on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.github.com/repos/octocat/example/issues' && req.method === 'POST') {
        return jsonResponse({ html_url: 'https://github.com/octocat/example/issues/42' }, 201)
      }
      if (req.url === 'https://mysub.zendesk.com/api/v2/tickets/9876.json' && req.method === 'PUT') {
        return jsonResponse({ ticket: { id: 9876, url: 'https://mysub.zendesk.com/api/v2/tickets/9876.json' } }, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      githubOwner: 'octocat',
      githubRepo: 'example',
      githubToken: 'gh-token',
      zendeskSubdomain: 'mysub',
      zendeskAccessToken: 'zd-token',
      fetch,
    }

    const payload: ZendeskTicketCreatedPayload = {
      type: 'zen:event-type:ticket.created',
      account_id: 12345,
      id: 'abc-123-def',
      time: '2025-01-15T10:30:00Z',
      zendesk_event_version: '2022-06-20',
      subject: 'zen:ticket:9876',
      detail: {
        id: '9876',
        subject: 'Support needed',
        description: 'Customer reports login failure',
        status: 'open',
        priority: 'normal',
        requester_id: '111',
        submitter_id: '222',
        assignee_id: null,
        organization_id: '333',
        group_id: '444',
        tags: ['support'],
        via: { channel: 'web' },
        created_at: '2025-01-15T10:29:00Z',
        updated_at: '2025-01-15T10:29:00Z',
      },
    }

    const result = await handle(payload, config)

    expect(result.githubIssueUrl).toBe('https://github.com/octocat/example/issues/42')
    expect(result.zendeskTicketId).toBe('9876')
    expect(calls).toHaveLength(2)

    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.github.com/repos/octocat/example/issues')
    expect(calls[0].json).toEqual({ title: 'Support needed', body: 'Customer reports login failure' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer gh-token')

    expect(calls[1].method).toBe('PUT')
    expect(calls[1].url).toBe('https://mysub.zendesk.com/api/v2/tickets/9876.json')
    expect(calls[1].json).toEqual({
      ticket: { comment: { body: 'GitHub issue created: https://github.com/octocat/example/issues/42', public: true } },
    })
    expect(calls[1].headers.get('authorization')).toBe('Bearer zd-token')
  })

  it('throws on missing detail.id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      githubOwner: 'o',
      githubRepo: 'r',
      githubToken: 't',
      zendeskSubdomain: 's',
      zendeskAccessToken: 't',
      fetch,
    }
    const payload = { ...SOURCE_EXAMPLE, detail: { ...SOURCE_EXAMPLE.detail, id: undefined } } as unknown as ZendeskTicketCreatedPayload
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: detail.id')
  })

  it('throws on missing detail.subject', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      githubOwner: 'o',
      githubRepo: 'r',
      githubToken: 't',
      zendeskSubdomain: 's',
      zendeskAccessToken: 't',
      fetch,
    }
    const payload = { ...SOURCE_EXAMPLE, detail: { ...SOURCE_EXAMPLE.detail, subject: undefined } } as unknown as ZendeskTicketCreatedPayload
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: detail.subject')
  })

  it('throws on missing detail.description', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      githubOwner: 'o',
      githubRepo: 'r',
      githubToken: 't',
      zendeskSubdomain: 's',
      zendeskAccessToken: 't',
      fetch,
    }
    const payload = { ...SOURCE_EXAMPLE, detail: { ...SOURCE_EXAMPLE.detail, description: undefined } } as unknown as ZendeskTicketCreatedPayload
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: detail.description')
  })

  it('throws on non-2xx GitHub response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ message: 'Not Found' }, 404))
    const config: ConnectorConfig = {
      githubOwner: 'o',
      githubRepo: 'r',
      githubToken: 't',
      zendeskSubdomain: 's',
      zendeskAccessToken: 't',
      fetch,
    }
    await expect(handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)).rejects.toThrow('HTTP 404 on POST https://api.github.com/repos/o/r/issues')
  })

  it('throws on non-2xx Zendesk response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.endsWith('/issues')) return jsonResponse({ html_url: 'https://github.com/o/r/issues/1' }, 201)
      return jsonResponse({ error: 'Unauthorized' }, 401)
    })
    const config: ConnectorConfig = {
      githubOwner: 'o',
      githubRepo: 'r',
      githubToken: 't',
      zendeskSubdomain: 's',
      zendeskAccessToken: 't',
      fetch,
    }
    await expect(handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)).rejects.toThrow('HTTP 401 on PUT https://s.zendesk.com/api/v2/tickets/9876.json')
    expect(calls).toHaveLength(2)
  })

  it('retries on 429 then succeeds', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.endsWith('/issues')) {
        if (calls.filter((c) => c.url === req.url).length === 0) {
          return jsonResponse({ message: 'rate limited' }, 429)
        }
        return jsonResponse({ html_url: 'https://github.com/o/r/issues/1' }, 201)
      }
      return jsonResponse({ ticket: { id: 9876 } }, 200)
    })
    const config: ConnectorConfig = {
      githubOwner: 'o',
      githubRepo: 'r',
      githubToken: 't',
      zendeskSubdomain: 's',
      zendeskAccessToken: 't',
      fetch,
    }
    vi.useFakeTimers()
    const promise = handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)
    await vi.runAllTimersAsync()
    const result = await promise
    expect(result.githubIssueUrl).toBe('https://github.com/o/r/issues/1')
    expect(calls.filter((c) => c.url.endsWith('/issues'))).toHaveLength(2)
  })

  it('retries up to maxRetries then throws', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ message: 'rate limited' }, 429))
    const config: ConnectorConfig = {
      githubOwner: 'o',
      githubRepo: 'r',
      githubToken: 't',
      zendeskSubdomain: 's',
      zendeskAccessToken: 't',
      fetch,
    }
    vi.useFakeTimers()
    const promise = handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)
    await vi.runAllTimersAsync()
    await expect(promise).rejects.toThrow('Max retries exceeded')
    expect(calls.filter((c) => c.url.endsWith('/issues'))).toHaveLength(4)
  })
})

